function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 2 || matrix.length > 50) return 'matrix needs 2 to 50 rows.';
  const n = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (n < 2 || n > 50) return 'matrix needs 2 to 50 columns.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'Every row must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < -1 || v > 100)) return 'Each value is an integer between -1 and 100.';
  }
  for (let col = 0; col < n; col++) {
    if (matrix.every(row => row[col] === -1)) return 'Each column needs at least one non-negative value.';
  }
  return null;
}

