function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'small' ? int(2, 5) : 50;
  const n = size === 'small' ? int(2, 5) : 50;
  const holes = size === 'small' ? [0.2, 0.5, 0.8][int(0, 2)] : [0.1, 0.4, 0.9][int(0, 2)];
  const top = size === 'small' ? [3, 100][int(0, 1)] : 100;
  const matrix = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < holes ? -1 : int(0, top))));
  // Each column needs a non-negative value; plant one where a column is all -1.
  for (let col = 0; col < n; col++) {
    if (matrix.every(row => row[col] === -1)) matrix[int(0, m - 1)][col] = int(0, top);
  }
  return [matrix];
}
